------------------
---- MONITORS ----
------------------

-- See https://wiki.hypr.land/Configuring/Basics/Monitors/
-- Test VM: one screen. Real machine adds main, right, laptop here.
hl.monitor({
    output   = "Virtual-1",
    mode     = "preferred",
    position = "0x0",
    scale    = 1,
})

-- Catch-all fallback: any unmatched screen still lights up. Never remove.
hl.monitor({
    output   = "",
    mode     = "preferred",
    position = "auto",
    scale    = "auto",
})


